FACETS = dict(explain='explain why the idea holds, or what problem it solves',
              predict='predict what happens in one concrete case when one thing changes, and say why',
              contrast='say how the idea differs from a near idea in one concrete case, and why the difference matters',
              apply='apply the idea to a new concrete case',
              judge='judge a wrong idea: say whether it holds in one concrete case, and why not')

def facet_for(c, depth:int, n:int=0) -> str:
    "The facet of a check at `depth` on concept `c`: `apply` from depth 4, else explain, predict, contrast (and judge, when `c` has wrong ideas) in turn by `n`, the count of earlier questions. '' for a choice."
    if depth <= 1: return ''
    if depth >= 4: return 'apply'
    fs = ['explain', 'predict', 'contrast'] + (['judge'] if c.get('wrong') else [])
    return fs[n % len(fs)]

def wrong_text(ws) -> str:
    "The wrong ideas `ws` as numbered lines for a prompt, or 'none known'."
    return '\n'.join(f"{i}. {w['think']}" + (f" (true: {w['fact']})" if w.get('fact') else '') for i, w in enumerate(wrong_ideas(ws))) or 'none known'

def _concept_block(c, ctx='', level=''):
    core = (f"What the learner must understand (the core): {c['core']}" if c.get('core') else
            f"Reference statement (the idea is in it; do not ask about its sizes, names or numbers): {c.get('statement') or '(none given)'}")
    return (f"Concept: {c['name']} (subject: {c.get('subject') or 'general'})\n{core}\nKnown wrong ideas:\n{wrong_text(c.get('wrong'))}\n"
            f"Learner: floor {DEPTHS[c.get('floor', 0)]}, ceiling {DEPTHS[c['ceiling']] if c.get('ceiling', 6) < 6 else 'not found yet'}"
            + (f"\n{level}" if level else '') + (f"\nFrom the learner's own vault (for facts only; do not ask about a detail of it):\n{ctx}" if ctx else ''))

def _way(m): return f"The way to teach this time: {way(m)}\n" if m in METHODS else ''

PLAIN_Q = ("Ask about the core, not about a detail of the statement. Use the real terms of the subject and one concrete case. "
           "Do not wrap the question in an analogy, a story or a picture that the learner must decode. An analogy is allowed only as: where does this analogy break? "
           "When the core is a rule or a convention of a text that one cannot reason out, never ask why it holds: ask the learner to apply it to a case.")

def question_prompt(c, depth, avoid=(), ctx='', bridge=(), read='', level='', facet='', target=''):
    "The prompt that writes one question on `c` at `depth` with `facet` (see `facet_for`); `target` is a seen misconception to aim at once; `bridge` names known ideas that a transfer question can connect to."
    kind, facet = KIND_AT[depth], facet or facet_for(c, depth)
    shape = ('{"question": str, "code": str, "options": [{"text": str, "misconception": str}], "correct": int, "answer": str, "core": str, "also": [str], "wrong": str}'
             if kind == 'choice' else '{"question": str, "code": str, "answer": str, "core": str, "also": [str], "wrong": str}')
    av = '\n'.join(f'- {q}' for q in avoid)
    ask = f"{FACETS[facet]} ({depth_ask(depth)})" if facet in FACETS else depth_ask(depth)
    return (f"{_concept_block(c, ctx, level)}\n\nWrite ONE question that makes the learner {ask}.\n"
            f"Aim it just past what they reliably know, so they must struggle a little.\n{PLAIN_Q}\n{prompt('question')}\n"
            + (f"Target this wrong idea that the learner showed before, in this question only: {target}\n" if target else '')
            + (f"Ideas that the learner knows well (connect to one only if the link is real): {'; '.join(bridge)}\n" if bridge else '')
            + (f"The learner just read this. Ask past it; do not ask them to repeat a sentence of it:\n{read}\n" if read else '')
            + (f"Do not repeat these earlier questions:\n{av}\n" if av else '')
            + "`answer` is a model answer that the learner will not see. `core` is one sentence: the idea that a correct answer must hold, in any words. "
            "`also` lists 0 to 2 bonus points that only raise the grade" + (": at this depth, one of them is an edge case or a transfer to a new case, and the answer needs it to pass" if depth >= 4 else '')
            + ". `wrong` is the wrong idea that a wrong answer is likely to show, from the known wrong ideas when one fits. "
            "Check each point: it answers the question as asked. Drop a point that the question does not ask. "
            "Never make a point a required word, a phrase, a size, or a step of a named method."
            + (" For options: 3 or 4, one correct (index in `correct`), each wrong one tied to a named misconception." if kind == 'choice' else '')
            + " When the question shows code, put the code only in `code`, with its line breaks and indents, and write `question` as the words after the code. Else `code` is ''."
            + f"\nReturn JSON: {shape}")

def with_code(text:str, code:str='', lang:str='python') -> str:
    "`text` after `code` in a fenced block, so the code keeps its lines; `text` alone when there is no code."
    return f"```{lang}\n{code.strip(chr(10))}\n```\n\n{text}" if code.strip() else text

# %% ../nbs/03_tutor.ipynb #br02
def bridges(c, concepts, n:int=3) -> list:
    "The names of up to `n` concepts known to depth 3 or more, for a transfer question on `c`: other subjects first, then linked ones."
    links = {*(c.get('prereqs') or ()), *(c.get('related') or ())}
    ks = [x for x in concepts if x['slug'] != c['slug'] and x.get('floor', 0) >= 3]
    return [x['name'] for x in sorted(ks, key=lambda x: (x.get('subject') == c.get('subject'), x['slug'] not in links, -x.get('floor', 0)))[:n]]

