def thread_text(q) -> str:
    "The conversation on `q` so far, one turn to a line, in order."
    def line(t):
        if t['who'] == 'tutor': return f"Tutor ({t.get('kind', 'reply')}): {t['text']}"
        return f"Learner: {t.get('text') or '(nothing)'}" + (f"\n  (think-aloud: {t['thinking']})" if t.get('thinking') else '')
    return '\n'.join(map(line, q.get('turns') or []))

GRADE_SP = """You grade one answer: what a learner says over a conversation on one question. The learner builds the answer over several messages.
A new message is often only a follow-up to your last nudge, not a full answer. Judge the reasoning in all their messages
together, including the think-aloud, not the wording.
- `core_met`: true when their messages together hold the core point in substance, in ANY words: their own words, an example that
  shows it, or a correct equation. A missing term, name, size or framing never fails it. A point that the question did not ask never fails it.
  A list of the page's terms, or a definition said again, with no reason that links them, is not the core.
  A right result with no reason, or from wrong reasoning, does not hold a core that has a reason in it.
- `also_met`: how many bonus points their messages hold, 0 to 2. A bonus point only raises the grade.
- `slip`: a slip that does not change the idea, in a few words: a typo, a wrong sum, a misread number, a loose or overstated
  word ("instantly", "always"). Else "". A slip is never a misconception, and a slip alone never fails the core.
- `misconception`: the wrong mental model behind a wrong answer, in under 12 words, or "". Only for a wrong model of the idea:
  never for a slip, a missing point, a short answer or "I don't know".
- `known`: the number of the known wrong idea that the misconception matches, or -1.
- `first_error`: what is missing or wrong in the core idea now, in one short sentence that you say to them, WITHOUT the fix.
  Say what is true, not what they think. BAD: "You assume that the key must be a condensed version of the value."
  GOOD: "The key does not have to be a short form of the value." Empty when the core is met.
- `feedback`: reply to their latest message. Never only "Correct.", and never only the model answer said again.
  When the core is met: confirm the core in one line, in their terms, and add one line that ties it to a next idea or a consequence.
  Name a slip in a few words, if there is one.
  When the result is right but the reason is missing, or their think-aloud says they guess or do not know: say the result is right,
  then ask for the reason ("Why does it hold?").
  When the core is not met: say in a few words what in their message is right, if anything. Name what is missing in the idea, in the
  terms of the core. Then ask ONE question about a concrete case where their idea predicts the wrong thing. At most 3 sentences.
  Use one question mark only. Never repeat an earlier tutor turn. Never give the answer.
- Show code in `feedback` only when it helps the next step, and then at most 4 lines. Never repeat code that is already in the
  question or in an earlier tutor turn.
- The way to teach shapes the lesson. It does not force code into every nudge, and it does not force equations or an analogy.
- When their latest message says they do not know a term or an idea ("I don't know what the loop means"), `feedback` first
  explains that term in one or two plain sentences, without the answer to the question. Then it asks its one question.
- Their messages often come from speech to text. Read past transcription noise: repeated words, a wrong homophone, a garbled
  term or formula, when the meaning is clear. When the latest message restates an earlier point, judge them together.
  Never mark them wrong for the transcription alone.
- `gaps`: each idea they say they do not know, as a short concept name in the subject ("weighted sum as a loop", not "the loop"); else [].
- `asks_for`: when they ask to be shown in a certain way ("show me with code", "with an equation"), one of code, maths, analogy,
  example, diagram, words; else "".
- `grade`: 0-10, as real partial credit. Give 7 when the core is met with no bonus point, and 8-10 with bonus points.
  Give 4-6 when part of the core is there. Give 0-3 when it is wrong or missing.
- Write `feedback` and `first_error` in ASD-STE100 Simplified Technical English, grade 9: short sentences, active voice.
  Speak to the learner as "you"; never say "the learner".
- Sound like a kind, clear teacher who sits next to them, not like a report. Make one point at a time. Do not start with
  "You assume", "Your answer", "It seems" or "The response". BAD: "Your answer fails to account for the bias term."
  GOOD: "Close. Now add the bias. Where does b go in the sum?" Say each point in your own plain words."""

def core_of(q) -> str:
    "The core point of question `q`: its `core`, else its rubric points together (a ready question, a lesson check, your own question)."
    return q.get('core') or '; '.join(map(str, q.get('rubric') or ())) or q.get('answer') or ''

def grade_prompt(q, answer, thinking='', confidence=None):
    "The prompt that grades the conversation on question `q`, with `answer` as the latest message of the learner."
    also = [a for a in q.get('also') or () if a]
    return (f"Concept: {q.name}\nCheck: {q.get('facet') or KIND_AT.get(q.depth, '')}\nQuestion: {q.question}\nModel answer (hidden from learner): {q.answer}\n"
            f"Core point (required, in any words): {core_of(q)}\nBonus points (they only raise the grade): {json.dumps(also, ensure_ascii=False)}\n"
            + (f"At this depth the answer also needs one bonus point to pass. When the core is met and no bonus point is, `feedback` says the core is right and asks one question that leads to the bonus point.\n" if q.depth >= 4 and also else '')
            + f"Known wrong ideas:\n{wrong_text(q.get('known_wrong'))}\n\nThe conversation so far, in order:\n{thread_text(q) or 'Tutor (question): ' + q.question}\n\n"
            f"Their latest message follows; it may be only a follow-up to the last tutor turn.\n"
            f"Learner's answer: {answer or '(none)'}\nLearner's think-aloud: {thinking or '(none)'}\nLearner's confidence: {'not given' if confidence is None else f'{confidence}/100'}\n\n"
            + (f"Passages from the learner's own sources (judge against these too, where they apply):\n{q.ctx}\n\n" if q.get('ctx') else '')
            + (f"{_way(q.get('method'))}In `feedback`, use this way only when it helps the next step, or when they ask for it. "
               "Keep it short: at most 4 lines of code or equations.\n\n" if q.get('method') in METHODS else '')
            + 'Return JSON: {"core_met": bool, "also_met": int, "grade": int, "first_error": str, "slip": str, "misconception": str, "known": int, "feedback": str, "gaps": [str], "asks_for": str}')

def passed(q, g) -> AttrDict:
    """The grade `g` of the model, made sure: `correct` is the core met (at depth 4 or more with one bonus point, when the question has one). A pass has a grade of 7 or more, and a core with no needed bonus point 6 or less, so it is no near pass.
    A slip or a met core has no misconception. A grade from an older model with only `correct` counts that as the core."""
    core = bool(g.get('core_met', g.get('correct')))
    try: n = int(g.get('also_met') or 0)
    except (TypeError, ValueError): n = 0
    ok = core and (q.get('depth', 3) < 4 or not [a for a in q.get('also') or () if a] or n >= 1)
    try: gr = int(g.get('grade') if g.get('grade') is not None else (7 if ok else 3))
    except (TypeError, ValueError): gr = 7 if ok else 3
    mis = '' if core or (g.get('slip') and not g.get('misconception')) else g.get('misconception') or ''
    return AttrDict({**g, 'correct': ok, 'core_met': core, 'also_met': n, 'grade': max(gr, 7) if ok else min(gr, 6) if core else gr, 'misconception': mis,
                     'first_error': '' if ok else g.get('first_error') or ''})

