OPEN_KIND = 'open-q'
def _qlock(qid) -> threading.RLock:
    "The lock of open question `qid`, so that one caller at a time loads, changes and writes it. A lock that no caller holds goes away."
    return keyed_lock(OPEN_KIND, qid, weak=True)

def _held(f):
    "Run `f(self, qid, ...)` under the lock of question `qid`. A second caller waits, then finds the question as the first caller left it."
    @functools.wraps(f)
    def _f(self, qid, *args, **kw):
        with _qlock(qid): return f(self, qid, *args, **kw)
    return _f

@patch
def open_q(self:Learning, qid:str) -> AttrDict|None:
    "The document of question `qid` as its meta, with the full question in `q`; None when the shelf does not have it."
    r = self.v.by_source(_src(OPEN_KIND, qid))
    return AttrDict({**meta_of(r), 'doc_id': r['id']}) if r else None

@patch
def put_open_q(self:Learning, q, status:str='open', end:str='') -> AttrDict|None:
    "Save question `q` with its status, under its lock. A closed question never opens again: then the save does nothing and gives None."
    with _qlock(q['id']):
        old = self.open_q(q['id']) or {}
        if old.get('status', 'open') != 'open' and status == 'open': return None
        tries, meta = q.get('tries') or [], q.get('meta') or {}
        m = dict(id=q['id'], status=status, end=end or old.get('end', ''), concept=q.get('concept', ''), session=q.get('session', ''),
                 walk=meta.get('walk'), step=meta.get('step'), confidence=tries[-1].get('confidence') if tries else None,
                 created=q.get('at') or old.get('created') or time.time(), updated=time.time(), q=dict(q))
        if old: self.v.set_meta(old['doc_id'], **m)   # the text stays, so it is not embedded again
        else: self.v.add(f"Open question: {q.get('question', '')}", title=f"Open question: {q.get('name') or q.get('concept', '')}",
                         source=_src(OPEN_KIND, q['id']), kind=OPEN_KIND, meta=m, force=True)   # its own document, also when another question has the same text
        return AttrDict(m)

