class Open(dict):
    "Open questions by id: in memory, saved on the shelf on each change, and loaded from the shelf after a restart."
    def __init__(self, learning:Learning): super().__init__(); self.learning = learning

    def load(self, qid):
        "Question `qid` from the shelf, kept in memory, when it is open; else None. A stale question closes as abandoned."
        if not isinstance(qid, str): return None
        with _qlock(qid):   # two callers that both miss get one copy
            if super().__contains__(qid): return super().__getitem__(qid)
            if (m := self.learning.open_q(qid)) is None or m.status != 'open': return None
            if stale(m): self.learning.put_open_q(m.q, 'closed', 'abandoned'); return None
            q = AttrDict(m.q)
            super().__setitem__(qid, q)
            return q

    def __missing__(self, qid):
        if (q := self.load(qid)) is None: raise KeyError(qid)
        return q

    def __contains__(self, qid): return super().__contains__(qid) or self.load(qid) is not None
    def get(self, qid, d=None): return self[qid] if qid in self else d
    def save(self, q): self.learning.put_open_q(q)
    def __setitem__(self, qid, q): super().__setitem__(qid, q); self.save(q)
    def __delitem__(self, qid): self.learning.put_open_q(super().pop(qid), 'closed', 'closed')

    def pop(self, qid, *d):
        if qid not in self:
            if d: return d[0]
            raise KeyError(qid)
        q = super().pop(qid)
        self.learning.put_open_q(q, 'closed', 'dropped')
        return q

