@patch
def ask_on(self:Tutor, c, depth:int, why:str='', session:str='', mode:str=None, method:str=None, meta:dict=None, read:str='') -> AttrDict:
    "Write a question on concept `c` at `depth` in a method from `choose` (or `method`), keep it open, and return it without its answer fields. `mode='drill'` uses your best method. `meta` goes in each attempt record; `read` is the text that the learner just read."
    asked = self.learning.attempts(c['slug'], limit=20).attrgot('question')
    q = AttrDict(id=uuid.uuid4().hex[:10], concept=c['slug'], name=c['name'], statement=c.get('statement', ''),
                 subject=c.get('subject', ''), floor=c.get('floor', 0), depth=depth, kind=KIND_AT[depth], why=why, session=session,
                 hints=[], tries=[], meta=dict(meta or {}), at=time.time())
    ps, p, st = self._ground(c), self.learning.profile(), self.learning.stats()
    last = first(self.learning.attempts(c['slug'], limit=5).filter(lambda a: a.get('final')))
    allowed = [w for w in TEXT_WAYS if w != last.get('method')] if mode != 'drill' and last and last.get('walk') else None   # review: not the way of the last walk check
    if method: q.method, note = method, ''
    else: q.method, note = choose(st, c.get('subject', ''), mode == 'drill' or weak(c), self.rng, p.get('explore', 'sometimes'),
                                  [EXAMPLES_TO[e] for e in p.examples if e in EXAMPLES_TO], allowed)
    if note: q.why = f'{why}; {note}'.lstrip('; ')
    q.who = '\n'.join(x for x in (profile_text(p), calibration_text(AttrDict(st.calib)) if st.calib else '', methods_text(st, c.get('subject', ''))) if x)
    q.update(ctx=ground_text(ps), grounds=[link_of(p) for p in ps], level=self.learning.level_of(c))
    q.known_wrong = wrong_ideas(c.get('wrong'))
    if (ck := self.checks.pop(c['slug'], None)):   # the check of a lesson counts for the method of the lesson
        q.update(question=ck[0], answer=ck[1], core=f"the prediction follows from the lesson, for this reason: {c['core']}" if c.get('core') else 'the prediction follows from the lesson', ready=True, method=ck[2], why=f'{why}; the check from the lesson'.lstrip('; '))
        q.rubric = [q.core]
    elif (r := _ready_q(c, depth, asked)): q.update(question=r['q'], answer=r.get('a', ''), rubric=r.get('rubric') or [r.get('a', '')], ready=True)
    else:
        c = understand(self.learning, self.ask, c) or c   # an old idea gets its core and wrong ideas once
        q.known_wrong, q.facet = wrong_ideas(c.get('wrong')), facet_for(c, depth, len(asked))
        aimed = {a.get('target') for a in self.learning.attempts(c['slug'], limit=20)}
        tg = next((m for m in reversed(c.get('misconceptions') or []) if m not in aimed), '')   # a seen misconception is the target once
        if tg: q.meta['target'] = tg
        qp, ask = question_prompt(c, depth, asked[:8], q.ctx, bridges(c, self.learning.concepts()) if depth == 5 else (), read, self.learning.level_of(c, profile=False), q.facet, tg), for_task(self.ask, 'question')
        r = ask_json(ask, qp, teach_sp('tutor'), need=('question',))
        if val('checks.one_ask') and asks_twice(r.get('question')):   # one more try, with the question that asked twice
            r = ask_json(ask, f"{qp}\n\nYour last question asked twice: {r['question']!r}. Write it again with one ask: one question word and one question mark.", teach_sp('tutor'), need=('question',))
        r = _plain_q(ask, r, c['name'])
        rub = [x for x in r.get('rubric') or () if isinstance(x, str)]
        also = [x for x in r.get('also') or () if isinstance(x, str) and x.strip()][:2] if isinstance(r.get('also'), list) else []
        core = r['core'] if isinstance(r.get('core'), str) and r['core'].strip() else (rub[0] if rub else c.get('core', ''))
        q.update(question=with_code(r['question'], r.get('code') or ''), answer=r.get('answer', ''), core=core, also=also or rub[1:3], rubric=[core, *(also or rub[1:3])],
                 wrong=r.get('wrong') if isinstance(r.get('wrong'), str) else '')
        if q.kind == 'choice' and r.get('options'):
            opts = list(enumerate(r['options']))
            random.shuffle(opts)
            q.options = [o for _, o in opts]
            q.correct = next(i for i, (j, _) in enumerate(opts) if j == r.get('correct', 0))
        elif q.kind == 'choice': q.kind = 'recall'
    q.turns = [dict(who='tutor', kind='question', text=q.question)]
    self.open[q.id] = q
    return public(q)

def _plain_q(ask, r, name) -> dict:
    "The reply `r` with its question and the texts of its options in plain English, from at most one model call. A plainer question that asks twice is not kept."
    os = [o for o in r.get('options') or () if isinstance(o, dict) and isinstance(o.get('text'), str)]
    new = plainly(ask, {'question': r['question'], **{f'option {i + 1}': o['text'] for i, o in enumerate(os)}}, [name])
    if asks_twice(new['question']) and not asks_twice(r['question']): new = {**new, 'question': r['question']}
    return {**r, 'question': new['question'], **({'options': [{**o, 'text': new[f'option {i + 1}']} for i, o in enumerate(os)]} if os else {})}

def public(q) -> AttrDict:
    "A question as the learner can see it: no model answer, no rubric, no correct option, no misconception tags."
    out = AttrDict({k: v for k, v in q.items() if k not in ('answer', 'rubric', 'correct', 'options', 'statement', 'ctx', 'grounds', 'who', 'level', 'core', 'also', 'wrong', 'known_wrong')})
    if q.get('options'): out.options = [o['text'] for o in q.options]
    return out

