@patch
def _grade(self:Tutor, q, answer, thinking, confidence):
    if q.kind == 'choice' and q.get('options'):
        try: i = int(answer)
        except (TypeError, ValueError): i = next((j for j, o in enumerate(q.options) if o['text'] == answer), -1)
        ok = i == q.correct
        mis = '' if ok or not (0 <= i < len(q.options)) else q.options[i].get('misconception', '')
        return AttrDict(correct=ok, grade=10 if ok else 0, misconception=mis, first_error=mis and f'This option assumes: {mis}',
                        feedback='Correct.' if ok else 'Not this one either. Which option is left?' if q.tries else 'Not this one. Look again at what each option assumes.')
    ask = for_task(self.ask, 'grade')
    g = passed(q, AttrDict(ask_json(ask, grade_prompt(q, answer, thinking, confidence), prompt('grade'))))
    return AttrDict({**g, **plainly(ask, {k: g[k] for k in ('feedback', 'first_error') if isinstance(g.get(k), str) and g[k]}, [q.name])})

GUESS = re.compile(r"\b(?:i\s+)?(?:don'?t|do not)\s+know\b|\bno idea\b|\bguess", re.I)
def unsure(confidence=None, thinking:str='') -> bool:
    "True when an answer is a guess: a confidence under `checks.high`, or a think-aloud that says 'I don't know', 'no idea' or 'guess'."
    return (confidence is not None and confidence < val('checks.high')) or bool(GUESS.search(thinking or ''))

WHY_PICK = 'That is the right option. You were not sure, so the next question asks why it holds.'

