class NoLesson(str):
    "The note that stands for a lesson when the model fails; a caller can tell it from a real lesson by its type."

@patch
def _lesson(self:Tutor, q, first_error:str='') -> str:
    "A short lesson on `q` from its first error. When the model fails, a note with the model answer."
    fb = ' '.join(x for f in LESSON_NOTES if (x := f(self, q)))
    ask = for_task(self.ask, 'lesson')
    try: lesson = plainly(ask, ask(teach_prompt(AttrDict({**q, 'fb': fb}) if fb else q, first_error), teach_sp('tutor')).strip(), [q.name], ['Check:'])
    except Exception as e: return NoLesson(f"The tutor could not write the lesson ({type(e).__name__}). The model answer is: {q.answer or 'not given'}")
    if 'Check:' in lesson: self.checks[q.concept] = (lesson.rsplit('Check:', 1)[1].strip(), lesson, q.get('method', ''))
    return lesson

def kept_wrong(q, g) -> str:
    "The misconception of grade `g` to keep on the concept: the known wrong idea that it matches, or one that the learner showed in two messages of question `q`; else ''."
    m, k, ws = g.get('misconception') or '', g.get('known'), q.get('known_wrong') or []
    if not m: return ''
    if type(k) is int and 0 <= k < len(ws): return ws[k]['think']
    return m if sum(bool(t.get('misconception')) for t in q.get('tries') or ()) >= 2 else ''

@patch
def _close(self:Tutor, q, correct, confidence, g, teach=False, answer='', thinking='', dont_know=False):
    # the lesson comes first: if the model fails here, nothing is saved yet, so a retry cannot count the same miss twice
    lw = (first((f(self, q) for f in LESSON_HOOKS), bool) or '') if teach else ''   # a hook can teach in another way; the miss still counts for the way of the question
    lesson = self._lesson(AttrDict({**q, 'method': lw}) if lw else q, g.get('first_error', '')) if teach else ''
    best = max((t.get('grade') or 0 for t in q.tries), default=0)
    if not correct and not dont_know and best >= val('checks.near'): correct, g = True, AttrDict({**g, 'grade': best, 'feedback': '', 'first_error': '', 'misconception': ''})   # the best try counts: a shaky pass
    c = self.learning.concept(q.concept)
    hints = len(q.hints) + val('checks.hints') * (bool(q.tries) or bool(q.get('guess')))   # a pass after a wrong try, or a guess, is never a clean pass
    u = update(c, q.depth, correct, confidence, hints, dont_know, kept_wrong(q, g))
    kind = u.pop('kind')
    self.learning.update(q.concept, **u)
    q.setdefault('turns', []).append(dict(who='tutor', kind='close', text=g.get('feedback', ''), lesson=lesson, outcome=kind, **({'way': lw} if lw else {})))
    q.aid = self.learning.record(q.concept, q.question, answer or (q.tries[-1]['answer'] if q.tries else ''), thinking, correct, confidence,
                         q.depth, q.kind, hints, dont_know, g.get('grade'), g.get('feedback', '') or lesson,
                         g.get('first_error', ''), g.get('misconception', ''), session=q.session, final=True, outcome=kind, thread=q.turns,
                         method=q.get('method', ''), gaps=q.get('gaps', []), **({'teach_method': lw} if lw else {}), **q.get('meta', {})).id
    if q.get('method') and not dont_know: self.learning.credit_method(q.method, q.subject, kind)   # "I don't know" used no method
    del self.open[q.id]
    self.shut[q.id] = q
    if len(self.shut) > 20: del self.shut[next(iter(self.shut))]
    self.closed += 1
    if self.observe_every and self.pool and self.closed % self.observe_every == 0: self.pool.submit(self._observe)
    r = AttrDict(done=True, correct=correct, outcome=kind, feedback=g.get('feedback', ''), first_error=g.get('first_error', ''),
                 lesson=lesson, lesson_way=lw, aid=q.aid, answer=q.answer if not correct else '', misconception=g.get('misconception', ''), floor=u.floor, ceiling=u.ceiling,
                 due=u.due, depth=q.depth, grounds=q.get('grounds', []), concept=q.concept, session=q.session)
    for f in CLOSE_HOOKS: r = f(self, q, r) or r
    return r

@patch
def _observe(self:Tutor):
    "Update the profile from the recent answers; a failure changes nothing."
    try: return observe(self.learning, self.ask)
    except Exception: return []

